import clsx from 'clsx';
import { useSearchParams } from 'react-router-dom';
import { useCodeValueName } from '~/entities/comcode/lib/use-code-value-name';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { COM_CODE } from '~/entities/comcode/model/constants';
import { DetailAmountItem } from '~/entities/wallet/ui/wallet-history-detail/detail-amount-item';
import { DetailDateItem } from '~/entities/wallet/ui/wallet-history-detail/detail-date-item';
import { DetailPaymentApproval } from '~/entities/wallet/ui/wallet-history-detail/detail-payment-approval';
import { DetailRefundApproval } from '~/entities/wallet/ui/wallet-history-detail/detail-refund-approval';
import { DetailTop } from '~/entities/wallet/ui/wallet-history-detail/detail-top';
import { DetailVoucherReissue } from '~/entities/wallet/ui/wallet-history-detail/detail-voucher-reissue';
import { RcppaySttusCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { WalletHistoryDetailTemplateProps } from '.';

export const RefundTemplate = ({ data }: WalletHistoryDetailTemplateProps) => {
  const { navigateBack } = useNavigate();
  const [searchParams] = useSearchParams();
  const trnscId = searchParams.get('trnscId');
  const { shortBankName } = useComBankInfo(data.fromInsttCd);
  const { codeName } = useCodeValueName(COM_CODE.TRANSACTION_TYPE, data.trnscTypeCd ?? '');

  const handleClickRefundedTransactions = () => {
    navigateBack();
  };

  return (
    <div className={clsx('has-btm-btn flex flex-auto flex-col')}>
      <div className="detail-area">
        <div className="detail-box">
          <DetailTop
            coinTypeNm={data.coinTypeNm ?? ''}
            reqWalletInsttNm={data.reqWalletInsttNm ?? ''}
            reqWalletInsttCd={data.reqWalletInsttCd ?? ''}
            title={data.title ?? ''}
            trnscTypeCdNm={codeName ?? ''}
          />
          <div className="detail-info">
            <ul>
              <DetailAmountItem
                label={i18n.t('refundAmount')}
                amount={Number(data.refundAmt)}
                rcppaySttusCd={RcppaySttusCd.입금코드}
                classStr={'repay'}
              >
                <div className="repay-info">
                  <dl className="flex w-full flex-col">
                    <dt>{i18n.t('refundInfo')}</dt>
                    <dd>
                      <div className="wallet-asset-info">
                        <span className={`type`} style={{ marginLeft: '10px' }}>
                          {data.reqWalletInsttNm}
                        </span>
                        |
                        <span className="type" style={{ marginLeft: '5px' }}>
                          {data.myAliasNm}
                        </span>
                      </div>
                      <p>
                        {data.trnscAmt?.toLocaleString() ?? ''}
                        {i18n.t('won')}
                      </p>
                    </dd>
                  </dl>
                </div>
                <DetailVoucherReissue vouchNm={data.vouchNm} vouchAmt={Number(data.refundVouchAmt ?? 0)} />
              </DetailAmountItem>

              <DetailDateItem label={i18n.t('dateTime')} date={data.refundDt ?? ''} />
              <DetailRefundApproval refundCd={data.refundCd ?? ''} />
              <DetailPaymentApproval approvalCd={data.approvalCd ?? ''} />
            </ul>
          </div>
        </div>
      </div>
      <div className="detail-btm-info">
        <div className="repay-desc">
          <dl>
            <dt>{i18n.t('refundNotice')}</dt>
            <dd>
              {i18n.t('text:refundNoticeDescVoucher')}
              {/* {data.vouchTyCd === VouchTypeCd.보조금정액
                ? i18n.t('text:refundNoticeDescVoucher')
                : i18n.t('text:refundNoticeDesc')} */}
            </dd>
          </dl>
        </div>
      </div>

      {trnscId && (
        <div className="btn-area" onClick={handleClickRefundedTransactions}>
          <button className="btm-btn app">{i18n.t('viewRefundedTransactions')}</button>
        </div>
      )}
    </div>
  );
};
