import clsx from 'clsx';
import { Fragment } from 'react/jsx-runtime';
import { z } from 'zod';
import { WalletHistoryDetailData } from '~/entities/wallet/api/dtos/wallet-history-detail';
import { RcppaySttusCd } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';

// Define the Zod schema for props
const detailVouchAmountItemSchema = z.object({
  label: z.string(),
  amount: z.number(),
  rcppaySttusCd: z.nativeEnum(RcppaySttusCd),
  classStr: z.string().optional(),
  labelClassStr: z.string().optional(),
  children: z.any().optional(),
});

// Infer the type from the schema
type Props = z.infer<typeof detailVouchAmountItemSchema>;
type PageProps = Props & { detailData: WalletHistoryDetailData };

export const DetailVouchAmountItem = (props: PageProps) => {
  // Validate props at runtime
  const { classStr, labelClassStr, label, amount, rcppaySttusCd, children } = detailVouchAmountItemSchema.parse(props);
  const flag = rcppaySttusCd === RcppaySttusCd.출금코드 ? '-' : '+';

  return (
    <Fragment>
      <li
        className={clsx({
          [classStr as string]: classStr,
          withdraw: rcppaySttusCd === RcppaySttusCd.출금코드,
          deposit: rcppaySttusCd === RcppaySttusCd.입금코드,
        })}
        style={{ display: 'block' }}
      >
        <div className={clsx({ [labelClassStr as string]: labelClassStr })}>
          <span>{label}</span>
          <div className="detail-amount">
            {flag} {(Number(props.detailData?.amt) + Number(props.detailData?.vouchAmt)).toLocaleString()}
            {i18n.t('won')}
          </div>
        </div>
        <div className="vouch-detail-amount">
          <span>
            {props.detailData?.reqWalletInsttNm} | {props.detailData?.myAliasNm}{' '}
          </span>
          <div className="detail-amount">
            {flag} {Number(props.detailData?.amt).toLocaleString()}
            {i18n.t('won')}
          </div>
        </div>
        <div className="vouch-detail-amount">
          <span>{props.detailData?.vouchNm}</span>
          <div className="detail-amount">
            {flag} {Number(props.detailData?.vouchAmt).toLocaleString()}
            {i18n.t('won')}
          </div>
        </div>
        {children}
      </li>
    </Fragment>
  );
};
