import { z } from 'zod';
import i18n from '~/shared/i18n/i18n';

const voucherReissueSchema = z.object({
  vouchNm: z.string().nullable().optional(),
  vouchAmt: z.number(),
});

type VoucherReissueProps = z.infer<typeof voucherReissueSchema>;

export const DetailVoucherReissue = (props: Partial<VoucherReissueProps>) => {
  const validated = voucherReissueSchema.parse(props);

  if (!validated.vouchNm) return null;

  return (
    <>
      <div className="pt-5">
        <span>바우처 재발행</span>
        <div className="detail-amount">1매</div>
      </div>
      <div className="repay-info">
        <dl className="flex w-full flex-col">
          <dd>
            <span>{validated.vouchNm}</span>
            <p>
              1매({validated.vouchAmt?.toLocaleString()}
              {i18n.t('won')})
            </p>
          </dd>
        </dl>
      </div>
    </>
  );
};
