import { ComCodeType } from '~/entities/comcode/model/constants';
import { useComCodeState } from './use-comcode-state';

export const useCodeValueName = (codeType: ComCodeType, codeValue?: string) => {
  const { comCode } = useComCodeState(codeType);

  const codeName = comCode?.tbSysCodeValueList?.find((item) => item.cdValue === codeValue)?.cdValueNm;

  return { codeName };
};
