import { useErrorBoundary } from '@suspensive/react';
import { isEmpty } from 'lodash-es';
import { FormProvider, SubmitHandler, useForm } from 'react-hook-form';
import { ISSUE_RECEIPT_CARRIER } from '~/entities/business/model/types';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useIssueReceiptMutation } from '~/entities/exchange/api/hooks/use-issue-receipt-mutation';
import { UserResponse } from '~/entities/pin/api/dtos/schemas';
import { getUserRes } from '~/entities/user/api/use-get-cstmr-query';
import { useWalletHistoryDetail } from '~/entities/wallet/lib/use-wallet-history-detail';
import { IssueReceiptResponseStatus } from '~/shared/api/dtos/enums';
import { createFormOptions } from '~/shared/constants/form';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';
import { overlay } from '~/shared/lib/overlay';
import { notiBar, snackBar } from '~/shared/lib/toast';
import { Select } from '~/shared/ui/selects';
import { TextInput } from '~/shared/ui/text-input/text-input';

export type Inputs = {
  cstmrNo: string; //고객번호
  ewaBizNo: string; //사업자번호
  trnscId: string; //현금영수증 송금거래번호
  amt: string; //거래금액
  usageType: string; //거래자구분 (0:소비자,1:사업자)
  idNo: string; //신분확인번호 (휴대폰번호/사업자등록번호)
};

export const ReceiptDialog = () => {
  const { detailData } = useWalletHistoryDetail();
  const userRes = getUserRes() as UserResponse;
  const { shortBankName } = useComBankInfo(detailData?.fromInsttCd);
  const { mutateAsync: issueReceipt } = useIssueReceiptMutation();
  const { openAlertDialog } = useAlertDialog();
  const formOptions = createFormOptions<Inputs>();

  const form = useForm<Inputs>({
    mode: 'all',
    defaultValues: {
      cstmrNo: userRes?.tbCstmrMastr?.cstmrNo || '',
      ewaBizNo: userRes?.tbCstmrMastr?.ewaBizNo || '',
      trnscId: detailData.trnscId,
      amt: detailData.trnscAmt,
      usageType: '0',
      idNo: '',
    },
  });
  const {
    register,
    setFocus,
    handleSubmit,
    getValues,
    setValue,
    formState: { isValid },
  } = form;

  const { setError } = useErrorBoundary();

  const onSubmit: SubmitHandler<Inputs> = async (data) => {
    if (isEmpty(data.idNo)) {
      snackBar(i18n.t('validation:checkPhoneNumOrBizNum'));
      return;
    }

    const param: Inputs = data;
    const response: any = await issueReceipt(param);

    if (response.response_status !== IssueReceiptResponseStatus.발급요청) {
      // 현금영수증 발급요청 실패 시
      fnFailIssueReceiptDialog(data);
      return;
    }
    notiBar(i18n.t('text:completeIssueReceipt'));
    overlay.closeAll();
  };

  const fnFailIssueReceiptDialog = (data: any) => {
    openAlertDialog({
      message: i18n.t('validation:failIssueReceiptConfirmation'),
      buttonLabel: [i18n.t('cancel'), i18n.t('confirm')],
      onConfirmClick: () => {
        onSubmit(data);
      },
      onCancelClick: () => {
        //아무것도 실행하지 않음
      },
    });
  };

  const handleClickCancel = () => {
    overlay.closeAll();
  };

  return (
    <div className="modal">
      {/* <div className="modal-top">
        <h2>{i18n.t('text:refundRequest')}</h2>
        </div> */}
      <div className="modal-body">
        <div className="repay-modal">
          <div className="detail-info">
            <ul>
              <li className="repay">
                <div className="repay-amount">
                  <span>{i18n.t('generalAmount')}</span>
                  <div className="detail-amount">
                    {Number(detailData.trnscAmt)?.toLocaleString()}
                    {i18n.t('won')}
                  </div>
                </div>
              </li>
            </ul>
          </div>
          <FormProvider {...form}>
            <form onSubmit={handleSubmit(onSubmit)}>
              <div className="mt-8">
                <Select
                  classStr="shrink-0"
                  placeholder={i18n.t('usageType')}
                  labels={Object.keys(ISSUE_RECEIPT_CARRIER)}
                  values={Object.values(ISSUE_RECEIPT_CARRIER)}
                  name="usageType"
                  option={{ required: '' }}
                  //disabled={formPhase === FormPhase.REQUESTED_AUTH_NUMBER}
                />
                <div className="gap-[10px]">
                  <TextInput
                    label={
                      getValues('usageType') === '0'
                        ? i18n.t('phoneNumberWithoutHyphens')
                        : i18n.t('businessNumberWithoutHyphens')
                    }
                    inputMode="numeric"
                    minLength={7}
                    maxLength={11}
                    {...register('idNo', formOptions.BUSINESS_NUMBER)}
                    disabled={false}
                  />
                </div>
              </div>
            </form>
          </FormProvider>
        </div>
      </div>
      <div className="modal-btn">
        <button type="button" className="btm-btn" onClick={handleClickCancel}>
          {i18n.t('cancel')}
        </button>
        <button type="button" className="btm-btn app" onClick={handleSubmit(onSubmit)}>
          {i18n.t('issueReceipt')}
        </button>
      </div>
    </div>
  );
};
