import clsx from 'clsx';
import { z } from 'zod';
import { RcppaySttusCd } from '~/shared/api/dtos/enums';

// Define the Zod schema for props
const detailAmountItemSchema = z.object({
  label: z.string(),
  amount: z.number(),
  rcppaySttusCd: z.nativeEnum(RcppaySttusCd),
  reqWalletInsttNm: z.string().optional(),
  myAliasNm: z.string().optional(),
  classStr: z.string().optional(),
  labelClassStr: z.string().optional(),
  children: z.any().optional(),
});

// Infer the type from the schema
type Props = z.infer<typeof detailAmountItemSchema>;

export const DetailAmountItem = (props: Props) => {
  // Validate props at runtime
  const { classStr, labelClassStr, label, amount, rcppaySttusCd, reqWalletInsttNm, myAliasNm, children } =
    detailAmountItemSchema.parse(props);
  const hasWalletInfo = Boolean(reqWalletInsttNm && myAliasNm);
  const amountPrefix = rcppaySttusCd === RcppaySttusCd.출금코드 ? '-' : '+';

  return (
    <li
      className={clsx({
        [classStr as string]: classStr,
        withdraw: rcppaySttusCd === RcppaySttusCd.출금코드,
        deposit: rcppaySttusCd === RcppaySttusCd.입금코드,
      })}
    >
      <div className={clsx({ [labelClassStr as string]: labelClassStr })}>
        <span>{label}</span>
        <div
          className={clsx('detail-amount', 'detail-amount-column', {
            'detail-amount-no-padding': !hasWalletInfo,
          })}
        >
          {hasWalletInfo && (
            <span className="detail-amount-wallet-info">
              {reqWalletInsttNm} | {myAliasNm}
            </span>
          )}
          <span className="detail-amount-value">
            {amountPrefix}
            {amount.toLocaleString()}원
          </span>
        </div>
      </div>
      {children}
    </li>
  );
};
