import { useErrorBoundary } from '@suspensive/react';
import i18n from '~/shared/i18n/i18n';
import { useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

type DetailPaymentInfoProps = {
  walletDpstr: string;
  amt: number;
  trnscDcsnDt: string;
  keyId: string;
};

export const DetailPaymentInfo = ({ walletDpstr, amt, trnscDcsnDt, keyId }: DetailPaymentInfoProps) => {
  const { navigate } = useNavigate();
  const { setError } = useErrorBoundary();
  if (!keyId) {
    setError(new Error('관련 결제 정보 키 값이 없습니다.'));
    return;
  }
  const handlePaymentDetailClick = () => {
    navigate(`${PATHS.myWallet.historyDetail}${keyId}`);
  };

  return (
    <div className="detail-btm-info">
      <button type="button" className="pay-info-top w-full" onClick={handlePaymentDetailClick}>
        <h3>{i18n.t('relatedPaymentInfo')}</h3>
        <span className="btn more-btn">
          <span>{i18n.t('viewDetails')}</span>
        </span>
      </button>
      <div className="pay-info-detail">
        <ul>
          <li>
            <span>{i18n.t('merchantInfo')}</span>
            <p>{walletDpstr}</p>
          </li>
          <li>
            <span>{i18n.t('paymentAmount')}</span>
            <p>
              {Number(amt ?? 0)?.toLocaleString()}
              {i18n.t('won')}
            </p>
          </li>
          <li>
            <span>{i18n.t('dateTime')}</span>
            <p>{trnscDcsnDt}</p>
          </li>
        </ul>
      </div>
    </div>
  );
};
