import { MutationOptions, useMutation } from '@tanstack/react-query';
import { RefundRequestDTO, RefundResponseDTO } from '~/entities/payment/api/dtos/refund';
import { paymentApi } from '~/entities/payment/api/payment-api';
import { CBDCAxiosError } from '~/shared/@types/error';

export const useRefund = (options?: MutationOptions<RefundResponseDTO, CBDCAxiosError, RefundRequestDTO>) => {
  const mutation = useMutation<RefundResponseDTO, CBDCAxiosError, RefundRequestDTO>({
    ...options,
    mutationFn: paymentApi.refund,
  });

  return {
    ...mutation,
  };
};
